// Code generated by ffi-eject for inline mode; DO NOT EDIT.
//
// The upstream fixture builder resolves symbols through purego, which inline mode
// has no module dependency on. This equivalent goes through the vendored loader.

//go:build (amd64 || arm64) && (darwin || freebsd || linux || netbsd)

package ffi_test

import (
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"testing"

	ffi "github.com/tmc/lib/nvidia/internal/ffi"
)

func buildSym(tb testing.TB, code, sym string) uintptr {
	tb.Helper()
	dir := tb.TempDir()
	src := filepath.Join(dir, "g.c")
	if err := os.WriteFile(src, []byte(code), 0o644); err != nil {
		tb.Fatal(err)
	}
	ext := ".so"
	if runtime.GOOS == "darwin" {
		ext = ".dylib"
	}
	lib := filepath.Join(dir, "libg"+ext)
	cc := os.Getenv("CC")
	if cc == "" {
		cc = "cc"
	}
	ccArgs := []string{"-shared", "-fPIC", "-o", lib, src}
	if runtime.GOOS == "darwin" {
		// Under Rosetta the test binary is amd64 while cc defaults to the host's
		// arm64, and dlopen then rejects the library as an incompatible
		// architecture. Name the architecture the binary was built for.
		arch := runtime.GOARCH
		if arch == "amd64" {
			arch = "x86_64"
		}
		ccArgs = append([]string{"-arch", arch}, ccArgs...)
	}
	if out, err := exec.Command(cc, ccArgs...).CombinedOutput(); err != nil {
		tb.Fatalf("cc: %v\n%s", err, out)
	}
	h, err := ffi.Open(lib)
	if err != nil {
		tb.Fatal(err)
	}
	fn, err := ffi.Sym(h, sym)
	if err != nil {
		tb.Fatal(err)
	}
	return fn
}
